import os,glob,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
files=glob.glob(d+'/../../sessions/*.jsonl')
print(sorted(files)[-8:])
G={}
for f in files:
    t=open(f,encoding='utf8',errors='ignore').read().replace('\\n','\n')
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

I=G['Demo pair 8 input']; O=G['Demo pair 8 output']
H,W=len(I),len(I[0]); bg=6
seen=set()
for r in range(H):
    for c in range(W):
        if I[r][c]==bg or (r,c) in seen: continue
        st=[(r,c)]; comp=[]
        while st:
            a,b=st.pop()
            if (a,b) in seen: continue
            seen.add((a,b)); comp.append((a,b))
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                na,nb=a+da,b+db
                if 0<=na<H and 0<=nb<W and I[na][nb]!=bg and (na,nb) not in seen: st.append((na,nb))
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        outvals={(rr,cc):O[rr][cc] for rr in range(r0,min(r1,H-1)+1) for cc in range(c0,min(c1,W-1)+1)}
        added=[(dr-r0,dc-c0,O[dr][dc]) for dr in range(r0,r1+1) for dc in range(c0,c1+1)
               if I[dr][dc]==bg and O[dr][dc]!=bg]
        print('size',len(comp),'bbox',r0,r1,c0,c1,'reladded',sorted(added))

