import collections
def comps_of(inp):
    Hh,Ww=len(inp),len(inp[0]); seen=set(); out=[]
    for r in range(Hh):
        for c in range(Ww):
            if inp[r][c]==6 or (r,c) in seen: continue
            st=[(r,c)]; comp=[]
            while st:
                a,b=st.pop()
                if (a,b) in seen: continue
                seen.add((a,b)); comp.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<Hh and 0<=nb<Ww and inp[na][nb]!=6 and (na,nb) not in seen: st.append((na,nb))
            out.append(comp)
    return out
