    Hh,Ww=len(inp),len(inp[0])
    cs=comps_of(inp)
    out=[row[:] for row in inp]
    # gather emission targets; mark occupied by seeds
    occ=collections.defaultdict(lambda:[(r,c)])
    for comp in cs:
        for p in comp: occ[p[0]+p[1]]=(p[0],p[1])
    # apply emissions: only to background cells adjacent-ish (offset); if target occupied by another seed -> merge
    tgt=collections.Counter()
    for comp in cs:
        for p in comp:
            v=inp[p[0]][p[1]]
            dr,dc=offs[v]
            tr,tc=p[0]+dr,p[1]+dc
            if 0<=tr<Hh and 0<=tc<Ww:
                if inp[tr][tc]==6: tgt[(tr,tc)]+=1
    for (tr,tc),n in tgt.items():
        out[tr][tc]=maps[tuple(sorted(set(tgt.keys())))[0]] if False else 1
    # that mapping is wrong; redo: assign colors per target based on which sources point there
    assign={}
    for comp in cs:
        for p in comp:
            v=inp[p[0]][p[1]]
            dr,dc=offs[v]
            tr,tc=p[0]+dr,p[1]+dc
            if 0<=tr<Hh and 0<=tc<Ww: assign.setdefault((tr,tc),[]).append((p,v))
    for (tr,tc),srcs in assign.items():
        # dedupe: if multiple distinct colors conflict, pick by count then first
        ccnt=collections.Counter(v for _,v in srcs)
        mx=max(ccnt.values()); top=[v for v,kk in ccnt.items() if kk==mx]
        out[tr][tc]=top[0]
    return out
